ls", "form.name": "Contact name", "form.role": "Your role", "form.email": "Business email", "form.phone": "Mobile number", "form.priority": "Your group’s main priority (optional)", "form.priorityPlaceholder": "For example, group reporting or supported workflows", "form.review": "Review meeting request", "form.back": "Back", "form.reviewTitle": "Your discovery meeting brief", "form.reviewNote": "Check your details, then send your request. Our team will contact you to arrange the meeting.", "form.openEmail": "Email it instead", "form.download": "Download the brief", "form.privacy": "Your details are sent securely to Fandaqah’s customer relationship system and used only to arrange your meeting.", "form.error": "Please complete the required fields with valid details.", "form.success": "Your brief is ready. Send it from your email app to request a meeting.", "form.downloaded": "Your meeting brief has been downloaded.", "form.phoneError": "Please enter a valid mobile number, for example 05XXXXXXXX.", "form.rejected": "Please check your details and try again.", "form.failed": "We couldn’t reach our system just now. Please try again, or email the brief instead.", "form.ref": "Reference:", "form.doneText": "A Fandaqah specialist will contact you shortly to arrange your discovery meeting.", "form.doneTitle": "Thank you. Your request is with our team.", "form.sending": "Sending…", "form.send": "Send my meeting request", "footer.tag": "Your hospitality, our priority.", "footer.platform": "Hotel groups & operators", "footer.scope": "Deployment, customisation and branding are agreed in the proposal. All dashboard screens and property data are illustrative.", "footer.rights": "© 2026 Fandaqah. All rights reserved.", "footer.contact": "Contact Fandaqah", "story.close": "Close story", "story.title": "Your group. A shared direction.", "story.label": "25-SECOND CAMPAIGN STORY · CONCEPT ANIMATION", "story.play": "Play", "story.pause": "Pause", "story.restart": "Restart", "story.1": "Managing a hotel group through disconnected systems?", "story.2": "See your group and each property clearly.", "story.3": "Align supported workflows with your brand.", "story.4": "Discuss a dedicated technology platform.", "story.scene1": "Disconnected systems", "story.scene2": "Group visibility", "story.scene3": "Your brand & workflows", "story.scene4": "Discovery workshop", "story.workflow": "Approved sample workflow", "story.sample": "Illustrative branding · Agreed scope", "day.mon": "M", "day.tue": "T", "day.wed": "W", "day.thu": "T", "day.fri": "F", "day.sat": "S", "day.sun": "S", "nav.close": "Close navigation", "aria.mainNav": "Main navigation", "aria.mobileNav": "Mobile navigation", "aria.scope": "Dashboard scope", "aria.progress": "Meeting request progress"}, "ar": {"meta.title": "فندقة 360 لمجموعات الفنادق | مجموعتك. استراتيجية واحدة.", "meta.description": "استكشف منصة فندقة المخصّصة لمجموعات الفنادق السعودية: هوية ومسارات عمل مدعومة وتقارير للمجموعة وخطة تنفيذ محددة النطاق. احجز اجتماعاً استكشافياً.", "skip": "انتقل إلى المحتوى", "nav.platform": "المنصة", "nav.brand": "مجموعتك", "nav.workshop": "الورشة الاستكشافية", "nav.faq": "الأسئلة الشائعة", "nav.cta": "لنتحدث", "nav.menu": "افتح قائمة التنقل", "campaign": "الحملة D · السلاسل المحلية والمشغّلون", "region": "للمجموعات الفندقية السعودية", "hero.eyebrow": "مجموعتك. استراتيجية تقنية واحدة.", "hero.title": "منصة تقنية مخصّصة.<br>مبنية حول<br><em>مجموعتك الفندقية.<\/em>", "hero.lead": "استكشف بيئة فندقة مخصّصة بهوية ومسارات عمل وتكاملات وتقارير للمجموعة وفق ما يتم الاتفاق عليه.", "hero.detail": "وحّد الإجراءات المدعومة عبر منشآتك مع شريك تقني واحد مسؤول وخطة تنفيذ واضحة ومحددة النطاق.", "cta.main": "احجز اجتماعاً استكشافياً للمجموعة", "hero.story": "شاهد قصة المجموعة", "hero.fit": "للملّاك والمشغّلين المسؤولين عن نحو <strong>10 منشآت أو أكثر.<\/strong>", "hero.imageAlt": "مشهد معماري توضيحي لثلاث منشآت فندقية سعودية يربطها مسار مرجاني واحد.", "hero.caption": "منشآت متعددة. توجه مشترك.", "hero.sample": "رؤية توضيحية للمجموعة", "hero.boardTitle": "مجموعتك، بصورة أوضح.", "hero.boardScope": "نظرة عامة للمجموعة", "hero.boardSub": "رؤية واحدة. وتفاصيل لكل منشأة.", "hero.12": "منشآت افتراضية", "hero.3": "لوحات منشآت معروضة", "hero.branding": "هوية توضيحية · بيانات افتراضية", "hero.propView": "لوحة المنشأة", "city.riyadh": "الرياض", "city.jeddah": "جدة", "city.khobar": "الخبر", "principle1.title": "هويتك.", "principle1.text": "هوية متفق عليها مع مجموعتك.", "principle2.title": "سياساتك.", "principle2.text": "مسارات عمل مدعومة تتوافق مع معاييرك.", "principle3.title": "تقنياتك.", "principle3.text": "شراكة تقنية واحدة بمسؤوليات واضحة.", "intro.kicker": "مبنية حول أسلوب تشغيلك", "intro.title": "منشآت متعددة.<br><em>توجه مشترك واحد.<\/em>", "intro.lead": "منصة تقنية فندقية مخصّصة مبنية حول مجموعتك.", "intro.text": "قد تستقبل منشآتك ضيوفاً مختلفين، في مدن مختلفة، وضمن هياكل تشغيل متنوعة. ابدأ باستراتيجية تقنية مشتركة تراعي هذه الاختلافات.", "intro.point1": "رؤية واضحة للمجموعة ولكل منشأة.", "intro.point2": "مواءمة مسارات العمل المدعومة مع هويتك.", "intro.point3": "اتفاق واضح على النطاق والمسؤوليات وخطة الإطلاق.", "platform.kicker": "من رؤية المجموعة إلى تفاصيل المنشأة", "platform.title": "الصورة الأشمل.<br><em>والتفاصيل المهمة.<\/em>", "platform.text": "استكشف لوحة التحكم التوضيحية. اختر منشأة لترى كيف يمكن ربط رؤية المجموعة بالتفاصيل التشغيلية لكل منشأة.", "platform.note": "عرض توضيحي فقط. يتم الاتفاق في عرض السعر على النشر والتخصيص والهوية والمؤشرات والتكاملات المدعومة.", "demo.group": "نظرة عامة للمجموعة", "demo.groupName": "مجموعتك الفندقية", "demo.overview": "نظرة عامة على المنشآت", "demo.propertyOverview": "نظرة عامة على المنشأة", "demo.sample": "هوية توضيحية", "demo.sampleData": "بيانات افتراضية · ليست شاشة منتج فعلية", "demo.period": "أسبوع افتراضي", "demo.properties": "المنشآت المعروضة", "demo.occupancy": "إشغال افتراضي", "demo.reports": "التقارير المتاحة", "demo.chart": "الإشغال حسب اليوم", "demo.summary": "تقارير المنشآت", "demo.property": "المنشأة", "demo.status": "حالة افتراضية", "demo.occupancyShort": "الإشغال", "demo.review": "لمراجعة المجموعة", "demo.preparing": "قيد الإعداد", "demo.progress": "مسار عمل توضيحي للتقارير", "demo.progress1": "إعداد المنشأة", "demo.progress2": "مراجعة المجموعة", "demo.progress3": "اعتماد المالية", "demo.tableNote": "ثلاث منشآت من أصل اثنتي عشرة منشأة افتراضية. جميع الأسماء والقيم ومسارات العمل توضيحية.", "demo.propertyNote": "مثال على رؤية المنشأة. تحدّد الصلاحيات والتقارير ومسارات الاعتماد خلال الاستكشاف.", "demo.chartLabel": "نسب إشغال توضيحية خلال سبعة أيام", "brand.kicker": "هويتك. سياساتك. تقنيات مجموعتك الفندقية.", "brand.title": "مخصّصة لمجموعتك.<br><em>نحدّدها معاً.<\/em>", "brand.text": "ابنِ شراكتك التقنية في قطاع الضيافة مع فندقة. نتفق على احتياجات مجموعتك، وما هو مدعوم، وكيفية تنفيذه.", "brand.previewTitle": "منصة تعبّر<br>عن مجموعتك.", "brand.sample": "هوية توضيحية", "brand.previewName": "مجموعتك الفندقية", "brand.previewBody": "هويتك. مسارات عمل متفق عليها. رؤية مشتركة.", "brand.tag1": "هوية المجموعة", "brand.tag2": "صلاحيات محددة", "brand.tag3": "مسارات عمل مدعومة", "brand.a1.title": "الهوية ومسارات العمل المدعومة", "brand.a1.text": "نتفق على الهوية البصرية والإجراءات التشغيلية المدعومة التي ترغب مجموعتك في توحيدها. ينفّذ التخصيص وفق نطاق متفق عليه ومعايير قبول واضحة.", "brand.a2.title": "التقارير والصلاحيات", "brand.a2.text": "نحدّد تقارير المجموعة ورؤى المنشآت ومن يمكنه الاطلاع على المعلومات أو تعديلها أو اعتمادها. تتضح مسؤوليات فرق المجموعة والمنشآت قبل الإطلاق.", "brand.a3.title": "التكاملات والاستضافة", "brand.a3.text": "نراجع أنظمتك الحالية والواجهات المطلوبة ونهج النشر ومتطلبات البيانات. توثّق الجدوى التقنية والموافقات والمسؤوليات في عرض السعر.", "brand.a4.title": "الدعم والمسؤولية", "brand.a4.text": "نتفق على نموذج الخدمة ومسؤوليات الدعم والتدريب ومسارات التصعيد مع شريك تقني واحد مسؤول. ونحدّد معاً خطة التنفيذ ونقاط المراجعة.", "brand.note": "الهوية والاستضافة والتخصيص ومسؤوليات الخدمة خاصة بكل عرض. تحدّد شروط العقد الملكية والحقوق الأخرى.", "workshop.kicker": "الورشة الاستكشافية للمجموعة", "workshop.title": "منصة أفضل تبدأ<br><em>بالأسئلة الصحيحة.<\/em>", "workshop.lead": "اجمع الملّاك وفرق التشغيل والتقنية والمالية في حوار واحد مركّز.", "workshop.text": "نرسم هيكل منشآتك وأولوياتك وآلية اتخاذ القرارات التقنية قبل إعداد عرض محدد النطاق. أحضر قائمة المنشآت والأنظمة الحالية ومتطلبات التقارير.", "workshop.owner": "المالك / الرئيس التنفيذي", "workshop.ops": "مدير العمليات / التشغيل", "workshop.it": "تقنية المعلومات", "workshop.finance": "المالية", "workshop.outcomeLabel": "مخرجات الورشة", "workshop.outcome": "ملخص موثّق لاحتياجات المجموعة وخطوات تالية متفق عليها نحو عرض واضح ومحدد النطاق.", "workshop.1.title": "هيكل المنشآت", "workshop.1.text": "المنشآت المملوكة والمُدارة وبنظام الامتياز، وعددها التقريبي، والجهة المخوّلة بالشراء التقني.", "workshop.2.title": "التقارير", "workshop.2.text": "المعلومات التي تحتاجها فرقك على مستوى المجموعة والمنشأة للمراجعة واتخاذ القرار.", "workshop.3.title": "الصلاحيات", "workshop.3.text": "من يطّلع ومن يعتمد، وما القرارات التي تبقى لدى كل منشأة.", "workshop.4.title": "التكاملات", "workshop.4.text": "الأنظمة الحالية والواجهات المطلوبة والجدوى ومسار الموافقات.", "workshop.5.title": "الاستضافة", "workshop.5.text": "تفضيلات النشر ومتطلبات البيانات والمسؤوليات المتفق عليها.", "workshop.6.title": "الدعم", "workshop.6.text": "توقعات الخدمة والتصعيد والتدريب والمسؤولون عن كل جانب.", "workshop.7.title": "التنفيذ", "workshop.7.text": "تجربة متفق عليها وتسلسل الإطلاق ومعايير القبول ومقاييس النجاح.", "journey.kicker": "مسار واضح من الحوار إلى الإطلاق", "journey.title": "ابدأ بالتوافق.<br><em>وتوسّع بخطة.<\/em>", "journey.text": "نحدّد العمل ونختبره مع منشآت متفق عليها، ثم نتوسّع عبر نقاط مراجعة موثّقة.", "journey.1.title": "الاستكشاف", "journey.1.text": "تأكيد هيكل المجموعة وصنّاع القرار والأولويات والمتطلبات.", "journey.1.output": "ملخص موثّق للمجموعة", "journey.2.title": "تحديد النطاق", "journey.2.text": "الاتفاق على المخرجات والواجهات والمسؤوليات والتكاليف ومعايير القبول.", "journey.2.output": "عرض واضح ومحدد النطاق", "journey.3.title": "التجربة", "journey.3.text": "التحقق من مسارات العمل المتفق عليها في منشآت مختارة قبل التوسع.", "journey.3.output": "مراجعة تجربة متفق عليها", "journey.4.title": "الإطلاق", "journey.4.text": "التوسّع على مراحل متفق عليها مع التدريب والدعم ونقاط متابعة التنفيذ.", "journey.4.output": "خطة إطلاق للمجموعة", "price.kicker": "تكاليف واضحة", "price.title": "عرض تتضح فيه جميع الأجزاء.", "price.text": "تُسعّر التهيئة والخدمة المستمرة والتخصيص المتفق عليه بشكل منفصل. يحدّد هيكل منشآتك ومتطلباتك المتفق عليها تفاصيل العرض.", "price.1": "التهيئة والتنفيذ", "price.2": "الخدمة المستمرة", "price.3": "التخصيص المتفق عليه", "faq.kicker": "قبل أن نلتقي", "faq.title": "أسئلة مهمة.<br><em>وتوقعات واضحة.<\/em>", "faq.1.q": "لمن تناسب منصة المجموعة؟", "faq.1.a": "للمشغّلين المحليين وملّاك المجموعات ومديري الأصول المسؤولين عن نحو 10 منشآت أو أكثر، بمشاركة التشغيل والتقنية والمالية على مستوى المجموعة. نؤكد وضع المنشآت المُدارة والمملوكة وبنظام الامتياز ومن يملك قرار شراء التقنية. تكون شركة إدارة الوجهات ذات صلة فقط إذا كانت تدير أصول الإقامة أو القرارات التقنية.", "faq.2.q": "ما نطاق التخصيص الممكن؟", "faq.2.a": "ينفّذ التخصيص وفق نطاق متفق عليه. تُقيّم الهوية ومسارات العمل المدعومة والتكاملات ومتطلبات التقارير خلال الاستكشاف، وتوثّق في عرض السعر مع المسؤوليات ومعايير القبول.", "faq.3.q": "هل تعني الهوية الخاصة نقل ملكية الكود المصدري؟", "faq.3.a": "لا تعني الهوية الخاصة نقل ملكية الكود المصدري أو تعديلات غير محدودة أو حصرية. يحدّد العقد حقوق الهوية والملكية والاستضافة والشروط التجارية الأخرى.", "faq.4.q": "هل يمكن ربط الأنظمة الحالية؟", "faq.4.a": "نراجع أنظمتك الحالية والواجهات المطلوبة، بما يشمل الجدوى التقنية والموافقات وجهد التنفيذ والمسؤوليات المستمرة. يشمل العرض التكاملات المدعومة والمتفق عليها فقط.", "faq.5.q": "كيف يتم تسعير عرض المجموعة؟", "faq.5.a": "تُسعّر التهيئة والخدمة المستمرة والتخصيص المتفق عليه بشكل منفصل. يعكس العرض هيكل المنشآت ونهج النشر والواجهات المدعومة ونطاق التنفيذ المتفق عليه مع مجموعتك.", "faq.6.q": "ماذا يسبق الإطلاق الأوسع؟", "faq.6.a": "نت