<script>(() => {
  'use strict';
  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => Array.from(root.querySelectorAll(selector));
  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
  let language = 'en';
  let scope = 'group';
  let formStep = 1;
  const t = key => MESSAGES[language][key] ?? MESSAGES.en[key] ?? key;
  const samples = {
    group: { count: 12, occupancy: 76, reports: 9, total: 12, bars: [64, 69, 72, 76, 83, 91, 77] },
    riyadh: { count: 1, occupancy: 81, reports: 1, total: 1, bars: [71, 76, 78, 81, 90, 95, 76] },
    jeddah: { count: 1, occupancy: 74, reports: 1, total: 1, bars: [59, 65, 71, 74, 84, 92, 73] },
    khobar: { count: 1, occupancy: 72, reports: 0, total: 1, bars: [62, 66, 67, 72, 77, 86, 74] }
  };
  function translated(node, key) {
    node.dataset.t = key;
    node.innerHTML = t(key);
  }
  function setScope(nextScope) {
    if (!samples[nextScope]) return;
    scope = nextScope;
    const sample = samples[scope];
    $$('.scope-tabs button').forEach(button => {
      const active = button.dataset.scope === scope;
      button.setAttribute('aria-selected', String(active));
      button.tabIndex = active ? 0 : -1;
    });
    $('#dashboard-panel').setAttribute('aria-labelledby', 'tab-' + scope);
    translated($('#scope-title'), scope === 'group' ? 'demo.group' : 'city.' + scope);
    translated($('#scope-eyebrow'), scope === 'group' ? 'demo.overview' : 'demo.propertyOverview');
    translated($('#chart-scope'), scope === 'group' ? 'demo.group' : 'city.' + scope);
    translated($('#dashboard-note'), scope === 'group' ? 'demo.tableNote' : 'demo.propertyNote');
    $('#metric-properties').innerHTML = sample.count + '<span>/ ' + sample.total + '</span>';
    $('#metric-occupancy').innerHTML = sample.occupancy + '<span>%</span>';
    $('#metric-reports').innerHTML = sample.reports + '<span>/ ' + sample.total + '</span>';
    $$('#chart-bars i').forEach((bar, i) => bar.style.setProperty('--bar', sample.bars[i] + '%'));
    $('.bar-chart').setAttribute('aria-label', t('demo.chartLabel') + ': ' + sample.bars.join('%, ') + '%.');
    $$('[data-property-row]').forEach(row => { row.hidden = scope !== 'group' && row.dataset.propertyRow !== scope; });
  }
  $$('.scope-tabs button').forEach((button, index) => {
    button.addEventListener('click', () => setScope(button.dataset.scope));
    button.addEventListener('keydown', event => {
      const buttons = $$('.scope-tabs button');
      let next;
      if (event.key === 'ArrowDown') next = (index + 1) % buttons.length;
      if (event.key === 'ArrowUp') next = (index - 1 + buttons.length) % buttons.length;
      if (event.key === 'ArrowRight') next = (index + (language === 'ar' ? -1 : 1) + buttons.length) % buttons.length;
      if (event.key === 'ArrowLeft') next = (index + (language === 'ar' ? 1 : -1) + buttons.length) % buttons.length;
      if (event.key === 'Home') next = 0;
      if (event.key === 'End') next = buttons.length - 1;
      if (next === undefined) return;
      event.preventDefault();
      setScope(buttons[next].dataset.scope);
      buttons[next].focus();
    });
  });
  $$('[data-select]').forEach(link => link.addEventListener('click', () => setScope(link.dataset.select)));

  const menuToggle = $('#menu-toggle');
  const mobileNav = $('#mobile-nav');
  function setMenu(open) {
    mobileNav.hidden = !open;
    menuToggle.setAttribute('aria-expanded', String(open));
    menuToggle.setAttribute('aria-label', t(open ? 'nav.close' : 'nav.menu'));
    $('use', menuToggle).setAttribute('href', open ? '#close' : '#menu');
  }
  menuToggle.addEventListener('click', () => setMenu(mobileNav.hidden));
  $$('a', mobileNav).forEach(link => link.addEventListener('click', () => setMenu(false)));
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape' && !mobileNav.hidden) { setMenu(false); menuToggle.focus(); }
  });
  matchMedia('(min-width: 961px)').addEventListener('change', event => { if (event.matches) setMenu(false); });
  const sectionObserver = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return;
      $$('.desktop-nav a').forEach(link => {
        const current = link.getAttribute('href') === '#' + entry.target.id;
        if (current) link.setAttribute('aria-current', 'location');
        else link.removeAttribute('aria-current');
      });
    });
  }, { rootMargin: '-15% 0px -65% 0px', threshold: 0 });
  ['platform', 'your-group', 'workshop', 'faq', 'discovery'].forEach(id => sectionObserver.observe($('#' + id)));

  const meetingForm = $('#meeting-form');
  const fields = {
    company: $('#company'), city: $('#city'), count: $('#property-count'), structure: $('#structure'),
    name: $('#contact-name'), role: $('#role'), email: $('#business-email'), phone: $('#phone'), priority: $('#priority')
  };
  const labels = { company: 'form.company', city: 'form.city', count: 'form.count', structure: 'form.structure', name: 'form.name', role: 'form.role', email: 'form.email', phone: 'form.phone', priority: 'form.priority' };
  const alert = $('#form-alert');
  const cleaned = key => fields[key].value.trim();
  const displayValue = key => ['count', 'structure'].includes(key) ? t('form.' + cleaned(key)) : cleaned(key);
  function showFormStep(step, focus = true) {
    formStep = step;
    $$('[data-step]', meetingForm).forEach(panel => {
      panel.hidden = Number(panel.dataset.step) !== step;
      if (panel.tagName === 'FIELDSET') panel.disabled = Number(panel.dataset.step) !== step;
    });
    $$('[data-progress]').forEach(item => {
      const value = Number(item.dataset.progress);
      item.classList.toggle('active', value === step);
      item.classList.toggle('complete', value < step);
      if (value === step) item.setAttribute('aria-current', 'step');
      else item.removeAttribute('aria-current');
    });
    alert.textContent = '';
    if (focus) {
      const target = step === 3 ? $('#review-heading') : step === 4 ? $('#done-heading') : $('input', $('[data-step="' + step + '"]', meetingForm));
      target.focus({ preventScroll: true });
    }
  }
  function validateStep(step) {
    let firstInvalid = null;
    $$('input, select, textarea', $('[data-step="' + step + '"]', meetingForm)).forEach(field => {
      let valid = field.checkValidity();
      if (field.required && !field.value.trim()) valid = false;
      if (field.minLength > 0 && field.value.trim().length < field.minLength) valid = false;
      if (field === fields.phone && !mobileOf(field.value)) valid = false;
      field.setAttribute('aria-invalid', String(!valid));
      if (!valid && !firstInvalid) firstInvalid = field;
    });
    if (firstInvalid) {
      alert.textContent = t(firstInvalid === fields.phone && cleaned('phone') ? 'form.phoneError' : 'form.error');
      firstInvalid.focus();
      return false;
    }
    alert.textContent = '';
    return true;
  }
  Object.values(fields).forEach(field => field.addEventListener('input', () => field.removeAttribute('aria-invalid')));
  $$('[data-next]', meetingForm).forEach(button => button.addEventListener('click', () => {
    if (validateStep(formStep)) showFormStep(Number(button.dataset.next));
  }));
  $$('[data-back]', meetingForm).forEach(button => button.addEventListener('click', () => showFormStep(Number(button.dataset.back))));
  function createBrief() {
    const title = language === 'ar' ? 'الحملة D — طلب اجتماع استكشافي للمجموعة' : 'Campaign D — Group discovery meeting request';
    const lines = Object.keys(fields).filter(key => cleaned(key)).map(key => t(labels[key]) + ': ' + displayValue(key));
    const closing = language === 'ar' ? 'أرغب في ترتيب اجتماع لاستكشاف منصة تقنية مخصّصة لمجموعتنا. يرجى التواصل لتنسيق الموعد ومشاركة المتطلبات الأولية.' : 'I would like to arrange a group discovery meeting to explore a dedicated hotel technology platform. Please contact me to agree a meeting time and initial requirements.';
    return title + '\n\n' + lines.join('\n') + '\n\n' + closing + '\n\n' + t('platform.note');
  }
  function buildReview() {
    const review = $('#review-list');
    review.replaceChildren();
    Object.keys(fields).forEach(key => {
      if (!cleaned(key)) return;
      const row = document.createElement('div');
      const term = document.createElement('dt');
      const detail = document.createElement('dd');
      term.textContent = t(labels[key]);
      detail.textContent = displayValue(key);
      if (['email', 'phone'].includes(key)) detail.dir = 'ltr';
      row.append(term, detail); review.append(row);
    });
    const subject = (language === 'ar' ? 'اجتماع استكشافي للمجموعة — ' : 'Group discovery meeting — ') + cleaned('company').replace(/[\r\n]/g, ' ');
    $('#email-request').href = 'mailto:info@fandaqah.com?subject=' + encodeURIComponent(subject) + '&body=' + encodeURIComponent(createBrief());
  }
  meetingForm.addEventListener('submit', event => {
    event.preventDefault();
    if (formStep === 1) { if (validateStep(1)) showFormStep(2); return; }
    if (formStep !== 2 || !validateStep(2)) return;
    buildReview(); showFormStep(3);
  });
  $('#email-request').addEventListener('click', () => { alert.textContent = t('form.success'); });

  /* ---------- the request goes to Fandaqah CRM through the lead proxy ----------
     No key in the browser: api/lead.php adds it on the server. The PHP copy of this page names its own proxy
     (<meta name="fq-lead-proxy">); the .html page (GitHub Pages preview) posts to the production proxy, allowed by origin. */
  const PLATFORM = 'fandaqah_tourism_platform_contact';
  const PROXY = ($('meta[name="fq-lead-proxy"]') || {}).content || 'https://fandaqah.com/landing/fandaqah-360/api/lead.php';
  const openedAt = Date.now();
  function mobileOf(raw) {
    // Saudi numbers become +966…; other countries need their + or 00 prefix; Arabic-Indic digits are accepted
    const v = raw.trim().replace(/[٠-٩۰-۹]/g, d => String(d.charCodeAt(0) & 0xF)), d = v.replace(/\D/g, '');
    if (/^(00966|966)[1-9]\d{8}$/.test(d)) return '+966' + d.replace(/^(00966|966)/, '');
    if (/^0[1-9]\d{8}$/.test(d)) return '+966' + d.slice(1);
    if (/^5\d{8}$/.test(d)) return '+966' + d;
    if (v.startsWith('+') && d.length >= 8 && d.length <= 15) return '+' + d;
    if (d.startsWith('00') && d.length >= 10 && d.length <= 17) return '+' + d.slice(2);
    return null;
  }
  const sendButton = $('#send-request');
  sendButton.addEventListener('click', async () => {
    if (sendButton.disabled) return;
    const id = crypto.randomUUID ? crypto.randomUUID() : Date.now().toString(36) + Math.random().toString(36).slice(2);
    const finish = () => { $('#form-ref').textContent = 'FQ-' + id.replace(/-/g, '').slice(0, 8).toUpperCase(); showFormStep(4); };
    // a bot fills the hidden field or sends faster than a person reads the form: it sees success, nothing is sent
    if (meetingForm.elements.website.value || Date.now() - openedAt < 3000) { finish(); return; }
    const qs = new URLSearchParams(location.search), utm = {};
    ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content'].forEach(k => { if (qs.get(k)) utm[k] = qs.get(k); });
    const en = key => MESSAGES.en[key] || key;
    const summary = Object.keys(fields).filter(key => key !== 'priority' && cleaned(key))
      .map(key => en(labels[key]).replace(/ \(optional\)$/, '') + ': ' + (['count', 'structure'].includes(key) ? en('form.' + cleaned(key)) : cleaned(key)));
    const note = cleaned('priority');
    const payload = {
      submission_id: id, name: cleaned('name'), email: cleaned('email').toLowerCase(), phone: mobileOf(cleaned('phone')), phone_raw: cleaned('phone'),
      company: cleaned('company'), city: cleaned('city'), role: cleaned('role'), property_count: cleaned('count'), ownership: cleaned('structure'),
      message: [...(note ? [note, '———'] : []), '[Fandaqah 360 · D Hotel groups · Group discovery meeting]', ...summary].join('\n'),
      customer_message: note || undefined, interest: 'group_discovery', interest_label: 'Group discovery meeting', segment: 'D',
      platform: PLATFORM, source: 'fandaqah_campaign_d_page', language, page_url: location.href.split('#')[0], submitted_at: new Date().toISOString(), ...utm
    };
    const label = $('span', sendButton), idle = label.textContent;
    sendButton.disabled = true; label.textContent = t('form.sending'); alert.textContent = '';
    let result = 'failed';
    for (let attempt = 0; attempt < 3 && result === 'failed'; attempt++) {
      const ctrl = new AbortController(), stop = setTimeout(() => ctrl.abort(), 12000);
      try {
        const res = await fetch(PROXY, { method: 'POST', body: JSON.stringify(payload), signal: ctrl.signal,
          headers: { 'Content-Type': 'application/json', Accept: 'application/json' } });
        if (res.ok) result = 'ok';
        else if (res.status === 404 || res.status === 405) break;                // the proxy is not on this host: say so now
        else if (res.status < 500 && res.status !== 429) result = 'rejected';   // a 4xx will not fix itself on retry
      } catch (err) { /* network or timeout: retry */ } finally { clearTimeout(stop); }
      if (result === 'failed' && attempt < 2) await new Promise(r => setTimeout(r, 1200 * (attempt + 1)));
    }
    sendButton.disabled = false; label.textContent = idle;
    if (result === 'ok') {
      if (window.dataLayer) window.dataLayer.push({ event: 'generate_lead', segment: 'D', interest: 'group_discovery' });
      finish();
    } else alert.textContent = t(result === 'rejected' ? 'form.rejected' : 'form.failed');
  });
  $('#download-brief').addEventListener('click', () => {
    const blob = new Blob(['\ufeff' + createBrief()], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url; anchor.download = 'Fandaqah-Group-Discovery-Brief.txt';
    document.body.append(anchor); anchor.click(); anchor.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    alert.textContent = t('form.downloaded');
  });

  const dialog = $('#story-dialog');
  let storyElapsed = 0;
  let storyPlaying = false;
  let storyLastFrame = 0;
  let storyFrame = 0;
  let storyScene = 0;
  const cuts = [0, 3, 10, 20];
  function paintStory(force = false) {
    const scene = storyElapsed < 3 ? 1 : storyElapsed < 10 ? 2 : storyElapsed < 20 ? 3 : 4;
    if (scene !== storyScene || force) {
      storyScene = scene;
      $('.story-stage').dataset.scene = String(scene);
      $$('[data-story-scene]').forEach(panel => { panel.hidden = Number(panel.dataset.storyScene) !== scene; });
      translated($('#story-caption'), 'story.' + scene);
      $$('[data-seek]').forEach(button => button.setAttribute('aria-current', String(Number(button.dataset.seek) === cuts[scene - 1])));
    }
    $('#story-progress-bar').style.width = Math.min(100, storyElapsed / 25 * 100) + '%';
    $('#story-time').textContent = '00:' + String(Math.floor(storyElapsed)).padStart(2, '0') + ' / 00:25';
    translated($('#story-play'), storyPlaying ? 'story.pause' : 'story.play');
    $('#story-play').setAttribute('aria-pressed', String(storyPlaying));
  }
  function storyTick(now) {
    if (!storyPlaying || !dialog.open) return;
    if (storyLastFrame) storyElapsed = Math.min(25, storyElapsed + (now - storyLastFrame) / 1000);
    storyLastFrame = now;
    if (storyElapsed >= 25) { storyPlaying = false; storyLastFrame = 0; }
    paintStory();
    if (storyPlaying) storyFrame = requestAnimationFrame(storyTick);
  }
  function pauseStory() {
    storyPlaying = false; storyLastFrame = 0; cancelAnimationFrame(storyFrame); paintStory();
  }
  function playStory() {
    if (storyElapsed >= 25) storyElapsed = 0;
    storyPlaying = true; storyLastFrame = 0; cancelAnimationFrame(storyFrame); paintStory();
    storyFrame = requestAnimationFrame(storyTick);
  }
  $$('.story-open').forEach(button => button.addEventListener('click', () => {
    storyElapsed = 0; dialog.showModal(); document.body.style.overflow = 'hidden'; paintStory(true);
    if (!reducedMotion.matches) playStory();
  }));
  $('#story-close').addEventListener('click', () => dialog.close());
  dialog.addEventListener('click', event => { if (event.target === dialog) dialog.close(); });
  dialog.addEventListener('close', () => { pauseStory(); document.body.style.overflow = ''; });
  $('#story-play').addEventListener('click', () => storyPlaying ? pauseStory() : playStory());
  $('#story-restart').addEventListener('click', () => { storyElapsed = 0; paintStory(true); if (!reducedMotion.matches) playStory(); });
  $$('[data-seek]').forEach(button => button.addEventListener('click', () => {
    storyElapsed = Number(button.dataset.seek); storyLastFrame = 0; paintStory(true);
  }));
  $('.story-cta').addEventListener('click', () => dialog.close());
  document.addEventListener('visibilitychange', () => { if (document.hidden && storyPlaying) pauseStory(); });
  reducedMotion.addEventListener('change', event => { if (event.matches) pauseStory(); });

  function setLanguage(nextLanguage, persist = false) {
    language = nextLanguage === 'ar' ? 'ar' : 'en';
    document.documentElement.classList.remove('i18n-wait');
    const root = document.documentElement;
    root.lang = language; root.dir = language === 'ar' ? 'rtl' : 'ltr';
    $$('[data-t]').forEach(node => { node.innerHTML = t(node.dataset.t); });
    $$('[data-alt]').forEach(node => { node.alt = t(node.dataset.alt); });
    $$('[data-aria]').forEach(node => node.setAttribute('aria-label', t(node.dataset.aria)));
    $$('[data-placeholder]').forEach(node => { node.placeholder = t(node.dataset.placeholder); });
    $$('[data-lang]').forEach(button => button.setAttribute('aria-pressed', String(button.dataset.lang === language)));
    document.title = t('meta.title');
    $('meta[name="description"]').content = t('meta.description');
    $('meta[property="og:title"]').content = t('meta.title');
    $('meta[property="og:description"]').content = t('meta.description');
    $('script[type="application/ld+json"]').textContent = JSON.stringify({
      '@context': 'https://schema.org', '@type': 'FAQPage', inLanguage: language,
      mainEntity: Array.from({ length: 7 }, (_, index) => ({
        '@type': 'Question', name: t('faq.' + (index + 1) + '.q'),
        acceptedAnswer: { '@type': 'Answer', text: t('faq.' + (index + 1) + '.a') }
      }))
    });
    $('.scope-tabs').setAttribute('aria-orientation', innerWidth <= 700 ? 'horizontal' : 'vertical');
    setMenu(false); setScope(scope); paintStory(true);
    if (formStep === 3) buildReview();
    if (persist) {
      try { localStorage.setItem('fandaqah-group-language-v3', language); } catch (_) { /* Private browser mode. */ }
      try { const url = new URL(location.href); url.searchParams.set('lang', language); history.replaceState(null, '', url); } catch (_) { /* Local file preview. */ }
    }
  }
  $$('[data-lang]').forEach(button => button.addEventListener('click', () => setLanguage(button.dataset.lang, true)));
  matchMedia('(max-width: 700px)').addEventListener('change', event => $('.scope-tabs').setAttribute('aria-orientation', event.matches ? 'horizontal' : 'vertical'));
  let savedLanguage = 'ar';   // Arabic by default
  try { savedLanguage = localStorage.getItem('fandaqah-group-language-v3') || 'ar'; } catch (_) { /* No storage required. */ }
  const requestedLanguage = new URLSearchParams(location.search).get('lang');
  showFormStep(1, false);
  setLanguage(requestedLanguage === 'ar' || requestedLanguage === 'en' ? requestedLanguage : savedLanguage);
})();
</script>
